  clientSecret: process.env.SCALEKIT_CLIENT_SECRET,
  issuer: process.env.SCALEKIT_ISSUER,
});

app.get("/callback", async (req, res) => {
  const { code, state } = req.query;

  if (!code || !state) {
    return res.status(400).json({ error: "Missing code or state" });
  }

  try {
    const { idToken } = await scalekit.authenticateWithCode(
      code,
      "http://localhost:3001/callback"
    );

    const decoded = jwt.decode(idToken);

    if (!decoded) {
      return res.status(400).json({ error: "Unable to decode idToken" });
    }

    const { email, name } = decoded;

    return res.json({ email, name });
  } catch (error) {
    return res.status(500).json({
      error: "Failed to authenticate with Scalekit",
      details: error?.message,
    });
  }
});

